components.css:
.ds-lead {
  width: fit-content;
  max-width: min(40em, 100%);
  margin: 0;
  font-family: "Sarabun", "Noto Sans Thai", Tahoma, sans-serif;
  font-size: 1.4rem;
  font-weight: 600;
  line-height: 1.65;
  color: var(--ink, #142433);
  text-wrap: pretty;
}
.ds-lead::after {
  content: "";
  display: block;
  height: 3px;
  width: 100%;
  margin-top: 12px;
  background: var(--bar, #1a6ea3);
  transform-origin: left center;
  animation: ds-rule 0.55s cubic-bezier(0.16, 1, 0.3, 1) both;
}
@keyframes ds-rule { from { transform: scaleX(0); } }
@media (min-width: 1100px) { .ds-lead { font-size: 1.65rem; } }
@media (max-width: 720px) { .ds-lead { font-size: 1.12rem; line-height: 1.6; } }
@media (prefers-reduced-motion: reduce) { .ds-lead::after { animation: none; } }

.ds-count {
  list-style: none;
  margin: 0;
  padding: 0;
  font-family: "Sarabun", "Noto Sans Thai", Tahoma, sans-serif;
  color: var(--ink, #142433);
}
.ds-count li {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px 18px;
  align-items: center;
  padding: 8px 0;
  border-top: 1px solid var(--line, #d5e0e8);
  border-bottom: 1px solid var(--line, #d5e0e8);
}
.ds-count strong { display: block; font-size: 1.05rem; line-height: 1.55; }
.ds-count-n {
  font-size: 4.25rem;
  font-weight: 700;
  line-height: 1.05;
  font-variant-numeric: tabular-nums;
  min-width: 1.6ch;
  text-align: center;
  border: 1px solid var(--blue, #0e4f78);
  padding: 0 10px;
  color: var(--blue, #0e4f78);
}
@media (max-width: 720px) {
  .ds-count-n { font-size: 2.65rem; }
  .ds-count li { padding: 4px 0; }
}

.ds-alert {
  list-style: none;
  margin: 0;
  padding: 0;
  font-family: "Sarabun", "Noto Sans Thai", Tahoma, sans-serif;
}
.ds-alert li {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px 18px;
  align-items: center;
  padding: 8px 0;
  border-top: 1px solid var(--line, #d5e0e8);
  border-bottom: 1px solid var(--line, #d5e0e8);
  background: var(--warn-bg, #fff5e8);
}
.ds-alert strong {
  display: block;
  font-size: 1.05rem;
  line-height: 1.55;
  color: var(--warn, #6e3d0c);
}
.ds-alert-n {
  font-size: 4.25rem;
  font-weight: 700;
  line-height: 1.05;
  font-variant-numeric: tabular-nums;
  min-width: 1.6ch;
  text-align: center;
  border: 1px solid var(--warn, #6e3d0c);
  padding: 0 10px;
  color: var(--warn, #6e3d0c);
}
@media (max-width: 720px) {
  .ds-alert-n { font-size: 2.65rem; }
  .ds-alert li { padding: 4px 0; }
}

.ds-ledger {
  width: 100%;
  border-collapse: collapse;
  font-family: "Sarabun", "Noto Sans Thai", Tahoma, sans-serif;
  color: var(--ink, #142433);
}
.ds-ledger caption {
  text-align: left;
  caption-side: top;
  font-weight: 700;
  font-size: 1.05rem;
  margin: 0 0 8px;
  line-height: 1.55;
}
.ds-ledger th {
  text-align: left;
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--muted, #3c5160);
  padding: 0 12px 8px 0;
  line-height: 1.5;
}
.ds-ledger td {
  font-size: 1.7rem;
  font-weight: 700;
  line-height: 1.25;
  font-variant-numeric: tabular-nums;
  padding: 12px 12px 4px 0;
  border-top: 1px solid var(--line, #d5e0e8);
  vertical-align: bottom;
}
.ds-ledger td span {
  display: block;
  margin-top: 4px;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--muted, #3c5160);
  line-height: 1.5;
}
@media (min-width: 720px) { .ds-ledger td { font-size: 2.15rem; } }

.ds-bars {
  list-style: none;
  margin: 0;
  padding: 0;
  font-family: "Sarabun", "Noto Sans Thai", Tahoma, sans-serif;
  color: var(--ink, #142433);
}
.ds-bars li { padding: 11px 0; border-top: 1px solid var(--line, #d5e0e8); }
.ds-bar-top { display: flex; justify-content: space-between; gap: 12px; align-items: baseline; }
.ds-bar-name .ds-th { display: block; font-weight: 700; line-height: 1.55; }
.ds-bar-name .ds-en { display: block; color: var(--muted, #3c5160); font-size: 0.92rem; line-height: 1.5; }
.ds-bar-val {
  flex: none;
  text-align: right;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1.45;
}
.ds-bar-val small { display: block; font-weight: 600; color: var(--muted, #3c5160); }
.ds-peak {
  display: inline-block;
  margin-left: 6px;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--blue, #0e4f78);
  letter-spacing: 0;
}
.ds-track {
  margin-top: 6px;
  height: 8px;
  background: var(--track, #e3eef4);
  border-radius: 99px;
  overflow: hidden;
}
.ds-fill { height: 100%; background: var(--bar, #1a6ea3); border-radius: 99px; }
.ds-fill-max { background: var(--blue, #0e4f78); }

.ds-procs {
  width: 100%;
  border-collapse: collapse;
  font-family: "Sarabun", "Noto Sans Thai", Tahoma, sans-serif;
  color: var(--ink, #142433);
}
.ds-procs caption {
  text-align: left;
  font-weight: 700;
  margin: 0 0 8px;
  caption-side: top;
}
.ds-procs th, .ds-procs td {
  text-align: left;
  padding: 10px 12px 10px 0;
  border-top: 1px solid var(--line, #d5e0e8);
  vertical-align: baseline;
  line-height: 1.55;
  overflow-wrap: anywhere;
}
.ds-procs th { font-size: 0.92rem; color: var(--muted, #3c5160); font-weight: 600; }
.ds-procs .ds-num { text-align: right; font-variant-numeric: tabular-nums; padding-right: 0; }
.ds-procs code {
  font-family: "Sarabun", "Noto Sans Thai", Tahoma, sans-serif;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.ds-proc-peak {
  display: inline-block;
  margin-left: 6px;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--blue, #0e4f78);
}

.ds-jumps a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  font-family: "Sarabun", "Noto Sans Thai", Tahoma, sans-serif;
  color: var(--blue, #0e4f78);
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 4px;
  text-decoration-thickness: 1px;
}
.ds-jumps a:hover { text-decoration-thickness: 2px; }
.ds-jumps a:focus-visible { outline: 3px solid var(--focus, #0b5cad); outline-offset: 3px; }

.ds-more {
  margin-top: 12px;
  border-top: 1px solid var(--line, #d5e0e8);
  padding-top: 8px;
  font-family: "Sarabun", "Noto Sans Thai", Tahoma, sans-serif;
}
.ds-more summary {
  cursor: pointer;
  font-weight: 700;
  min-height: 44px;
  display: flex;
  align-items: center;
  color: var(--blue, #0e4f78);
}
.ds-more summary:hover { text-decoration: underline; text-underline-offset: 3px; }
.ds-more summary:focus-visible { outline: 3px solid var(--focus, #0b5cad); outline-offset: 3px; }

.ds-error {
  margin: 0;
  font-family: "Sarabun", "Noto Sans Thai", Tahoma, sans-serif;
  color: #7f1d1d;
  background: #fdecec;
  padding: 12px 14px;
  border-radius: 2px;
  line-height: 1.7;
}

.ds-steps {
  list-style: none;
  margin: 0;
  padding: 0;
  counter-reset: ds-step;
  font-family: "Sarabun", "Noto Sans Thai", Tahoma, sans-serif;
  color: var(--ink, #142433);
}
.ds-steps li {
  display: grid;
  grid-template-columns: 2.2rem 1fr;
  gap: 10px;
  padding: 10px 0;
  border-top: 1px solid var(--line, #d5e0e8);
  line-height: 1.6;
}
.ds-steps li::before {
  counter-increment: ds-step;
  content: counter(ds-step);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--blue, #0e4f78);
}
.ds-steps b { font-weight: 700; }
.ds-steps span { display: block; color: var(--muted, #3c5160); }
